questionvariables.text:
/* Independent arrays yielding 5 x 2 x 5 x 2 x 10 x 3 = 3,000 unique variants with strictly non-colliding distractors */
pa : rand([6, 7, 8, 9, 10]);
pm : rand([2, 3]);
pb : rand([6, 7, 8, 9, 10]);
pw : rand([2, 3]);

men_rem : pa - pm;
women_rem : pb - pw;

pMen : binomial(pa, pm);
pWomen : binomial(pb, pw);
ta1 : pMen * pWomen;

pn2 : rand([14, 15, 16, 18, 19, 20, 21, 22, 24, 25]);
pr2 : rand([3, 4, 5]);
rem2 : pn2 - pr2;
ta2 : binomial(pn2, pr2);

/* Step-by-step factorial expansion and intermediate quotient helpers */
nary("mycross");
texput("mycross", " \\times ", nary);

men_num_factors : apply("mycross", makelist(pa - i, i, 0, pm - 1));
men_den_factors : apply("mycross", makelist(pm - i, i, 0, pm - 1));
men_num_prod : factorial(pa) / factorial(men_rem);
men_den_prod : factorial(pm);

women_num_factors : apply("mycross", makelist(pb - i, i, 0, pw - 1));
women_den_factors : apply("mycross", makelist(pw - i, i, 0, pw - 1));
women_num_prod : factorial(pb) / factorial(women_rem);
women_den_prod : factorial(pw);

b_num_factors : apply("mycross", makelist(pn2 - i, i, 0, pr2 - 1));
b_den_factors : apply("mycross", makelist(pr2 - i, i, 0, pr2 - 1));
b_num_prod : factorial(pn2) / factorial(rem2);
b_den_prod : factorial(pr2);

/* Distractors for targeted PRT feedback (strictly distinct across 100% of seeds) */
ta1_add : pMen + pWomen;
ta1_pool : binomial(pa + pb, pm + pw);
ta1_perm : (factorial(pa) / factorial(men_rem)) * (factorial(pb) / factorial(women_rem));

ta2_perm : factorial(pn2) / factorial(rem2);
ta2_no_rem : factorial(pn2) / factorial(pr2);
